import math

B = [0.6961663, 0.4079426, 0.8974794]
C = [0.0684043**2, 0.1162414**2, 9.896161**2]

def n_silica(lam_um):
    l2 = lam_um**2
    return math.sqrt(1 + sum(b * l2 / (l2 - c) for b, c in zip(B, C)))

def group_index(lam_um, h=1e-5):
    dn = (n_silica(lam_um + h) - n_silica(lam_um - h)) / (2 * h)
    return n_silica(lam_um) - lam_um * dn

import math

HB2M = 0.0380998
E2 = 1.439965
EG, ME, MH, EPS = 1.74, 0.13, 0.45, 10.6

def brus_gap(d_nm):
    R = d_nm / 2
    return EG + HB2M * math.pi**2 / R**2 * (1 / ME + 1 / MH) - 1.786 * E2 / (EPS * R)

def diameter_for(wavelength_nm):
    target = 1239.84 / wavelength_nm
    lo, hi = 3.0, 20.0                 # the gap falls steadily as the dot grows in this range
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if brus_gap(mid) > target:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

exercises.solution:
```python
def brus_gap(d_nm):
    R = d_nm / 2
    return EG + HB2M * math.pi**2 / R**2 * (1 / ME + 1 / MH) - 1.786 * E2 / (EPS * R)

def diameter_for(wavelength_nm):
    target = 1239.84 / wavelength_nm
    lo, hi = 3.0, 20.0
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if brus_gap(mid) > target:
            lo = mid      # gap too large: make the dot bigger
        else:
            hi = mid
    return 0.5 * (lo + hi)
```

The model asks for a dot about 6.06 nm across to emit at 600 nm, and about 4.45 nm for green at 520 nm. Bisection is safe because the gap falls monotonically with size above about 2 nm (below that, the Coulomb term makes the formula misbehave as well as become inaccurate). Real syntheses aim for a target emission and stop the crystal growth when it is reached, monitoring the absorption peak; the measured size–colour relation differs from the Brus prediction, increasingly so for small dots.
